import React, { useEffect, useState, useCallback } from 'react';
import clientService from '../../services/clientService';
import PageHeader from '../../components/common/PageHeader';
import DataTable from '../../components/common/DataTable';
import Modal from '../../components/common/Modal';
import '../../components/common/shared.css';

// ✅ FIX: Champs alignés avec CreateClientRequest.java backend
// AVANT (cassé) : { name, email, phone, address }
// APRÈS (correct): { firstName, lastName, email, phone, cin }
const EMPTY_FORM = { firstName: '', lastName: '', email: '', phone: '', cin: '' };

const ClientForm = ({ initial = EMPTY_FORM, onSubmit, onClose, loading }) => {
  const [form, setForm] = useState(() => {
    // Si l'objet vient avec "name" (ancien format), on le sépare
    if (initial.firstName !== undefined) return { ...EMPTY_FORM, ...initial };
    const parts = (initial.name || '').split(' ');
    return {
      firstName: parts[0] || '',
      lastName:  parts.slice(1).join(' ') || '',
      email:     initial.email   || '',
      phone:     initial.phone   || '',
      cin:       initial.cin     || '',
    };
  });
  const [errors, setErrors] = useState({});

  const validate = () => {
    const e = {};
    if (!form.firstName.trim()) e.firstName = 'Prénom requis';
    if (!form.lastName.trim())  e.lastName  = 'Nom requis';
    if (!form.email.trim())     e.email     = 'Email requis';
    else if (!/\S+@\S+\.\S+/.test(form.email)) e.email = 'Email invalide';
    return e;
  };

  const handle = ({ target: { name, value } }) => {
    setForm(p => ({ ...p, [name]: value }));
    if (errors[name]) setErrors(p => ({ ...p, [name]: '' }));
  };

  const submit = (e) => {
    e.preventDefault();
    const e2 = validate();
    if (Object.keys(e2).length) { setErrors(e2); return; }
    onSubmit(form);
  };

  return (
    <form onSubmit={submit}>
      <div className="form-grid">
        {/* ✅ FIX: firstName au lieu de name */}
        <div className="form-group">
          <label className="form-label">Prénom *</label>
          <input name="firstName" className="form-input" value={form.firstName} onChange={handle} placeholder="Mohammed" />
          {errors.firstName && <span className="form-error">{errors.firstName}</span>}
        </div>
        {/* ✅ FIX: lastName ajouté */}
        <div className="form-group">
          <label className="form-label">Nom *</label>
          <input name="lastName" className="form-input" value={form.lastName} onChange={handle} placeholder="Alami" />
          {errors.lastName && <span className="form-error">{errors.lastName}</span>}
        </div>
        <div className="form-group">
          <label className="form-label">Email *</label>
          <input name="email" type="email" className="form-input" value={form.email} onChange={handle} />
          {errors.email && <span className="form-error">{errors.email}</span>}
        </div>
        <div className="form-group">
          <label className="form-label">Téléphone</label>
          <input name="phone" type="tel" className="form-input" value={form.phone} onChange={handle} placeholder="0600000000" />
        </div>
        {/* ✅ FIX: cin au lieu de address (champ requis par le backend) */}
        <div className="form-group">
          <label className="form-label">CIN</label>
          <input name="cin" className="form-input" value={form.cin} onChange={handle} placeholder="AB123456" />
          <small style={{ color: '#888', fontSize: '0.75rem' }}>
            Sert de mot de passe initial pour le client
          </small>
        </div>
      </div>
      <div className="form-actions">
        <button type="button" className="btn btn--outline" onClick={onClose}>Annuler</button>
        <button type="submit" className="btn btn--primary" disabled={loading}>
          {loading ? <span className="dt-spinner" /> : 'Enregistrer'}
        </button>
      </div>
    </form>
  );
};

const ClientsPage = () => {
  const [clients, setClients] = useState([]);
  const [loading, setLoading] = useState(true);
  const [modal, setModal]     = useState(null);
  const [saving, setSaving]   = useState(false);
  const [search, setSearch]   = useState('');

  const load = useCallback(() => {
    setLoading(true);
    clientService.getAll()
      .then(setClients)
      .catch(() => {})
      .finally(() => setLoading(false));
  }, []);

  useEffect(() => { load(); }, [load]);

  const handleCreate = async (form) => {
    setSaving(true);
    try {
      // ✅ FIX: payload exact attendu par CreateClientRequest.java
      await clientService.create({
        firstName: form.firstName.trim(),
        lastName:  form.lastName.trim(),
        email:     form.email.trim(),
        phone:     form.phone   || null,
        cin:       form.cin     || null,
      });
      setModal(null);
      load();
    } catch (err) { alert(err.message); }
    finally { setSaving(false); }
  };

  const handleEdit = async (form) => {
    setSaving(true);
    try {
      await clientService.update(modal.client.id, {
        firstName: form.firstName.trim(),
        lastName:  form.lastName.trim(),
        email:     form.email.trim(),
        phone:     form.phone   || null,
        cin:       form.cin     || null,
      });
      setModal(null);
      load();
    } catch (err) { alert(err.message); }
    finally { setSaving(false); }
  };

  const handleDelete = async (id) => {
    if (!window.confirm('Supprimer ce client ?')) return;
    try { await clientService.delete(id); load(); }
    catch (err) { alert(err.message); }
  };

  const filtered = clients.filter(c =>
    !search ||
    c.fullName?.toLowerCase().includes(search.toLowerCase()) ||
    c.firstName?.toLowerCase().includes(search.toLowerCase()) ||
    c.lastName?.toLowerCase().includes(search.toLowerCase()) ||
    c.email?.toLowerCase().includes(search.toLowerCase())
  );

  // ✅ FIX: utilise fullName (retourné par ClientResponse.java)
  const columns = [
    { key: 'fullName', label: 'Nom complet',
      render: r => r.fullName || `${r.firstName || ''} ${r.lastName || ''}`.trim() },
    { key: 'email',    label: 'Email' },
    { key: 'phone',    label: 'Téléphone', render: r => r.phone || '—' },
    { key: 'cin',      label: 'CIN',       render: r => r.cin   || '—' },
  ];

  return (
    <div>
      <PageHeader
        title="Gestion des clients"
        subtitle={`${clients.length} client${clients.length > 1 ? 's' : ''} enregistrés`}
        action={
          <button className="btn btn--primary" onClick={() => setModal('create')}>
            + Ajouter client
          </button>
        }
      />

      <div style={{ marginBottom: '1rem' }}>
        <input
          type="text"
          className="form-input"
          placeholder="Rechercher par nom ou email…"
          value={search}
          onChange={e => setSearch(e.target.value)}
          style={{ maxWidth: 340 }}
        />
      </div>

      <DataTable
        columns={columns}
        data={filtered}
        loading={loading}
        empty="Aucun client trouvé."
        actions={row => (
          <div style={{ display: 'flex', gap: 6 }}>
            <button className="btn btn--sm btn--outline"
              onClick={() => setModal({ type: 'edit', client: row })}>
              Modifier
            </button>
            <button className="btn btn--sm btn--danger"
              onClick={() => handleDelete(row.id)}>
              Supprimer
            </button>
          </div>
        )}
      />

      {modal === 'create' && (
        <Modal title="Ajouter un client" onClose={() => setModal(null)}>
          <ClientForm onSubmit={handleCreate} onClose={() => setModal(null)} loading={saving} />
        </Modal>
      )}
      {modal?.type === 'edit' && (
        <Modal title="Modifier le client" onClose={() => setModal(null)}>
          <ClientForm initial={modal.client} onSubmit={handleEdit}
            onClose={() => setModal(null)} loading={saving} />
        </Modal>
      )}
    </div>
  );
};

export default ClientsPage;
